export const supportMyThread = <ThrowOnError extends boolean = false>(options?: Options<SupportMyThreadData, ThrowOnError>) => (options?.client ?? client).get<SupportMyThreadResponses, SupportMyThreadErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/support/me',
    ...options
});

/**
 * Gửi một tin cho đội ngũ hỗ trợ
 *
 * Mỗi người có ĐÚNG MỘT luồng, tạo tự động ở lần gửi đầu tiên. Nội dung đi qua cổng cụm từ cấm như mọi bề mặt nhập liệu khác.
 */
export const supportSend = <ThrowOnError extends boolean = false>(options?: Options<SupportSendData, ThrowOnError>) => (options?.client ?? client).post<SupportSendResponses, SupportSendErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/support/me/messages',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options?.headers
    }
});

/**
 * Đánh dấu đã đọc câu trả lời của master
 *
 * Tắt chấm đỏ. Gọi được cả khi chưa có luồng nào — không phải lỗi.
 */
export const supportMarkRead = <ThrowOnError extends boolean = false>(options?: Options<SupportMarkReadData, ThrowOnError>) => (options?.client ?? client).post<SupportMarkReadResponses, SupportMarkReadErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/support/me/read',
    ...options
});

/**
 * Hàng đợi hỗ trợ (master)
 *
 * Mặc định chỉ trả luồng ĐANG CHỜ trả lời (`waiting=true`) — gửi `waiting=false` để xem toàn bộ. Không kèm `messages`: danh sách chỉ cần dòng xem trước.
 */
export const supportQueue = <ThrowOnError extends boolean = false>(options?: Options<SupportQueueData, ThrowOnError>) => (options?.client ?? client).get<SupportQueueResponses, SupportQueueErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/support/threads',
    ...options
});

/**
 * Đọc một luồng hỗ trợ (master)
 *
 * Mở ra là đánh dấu master đã xem, nên luồng rời khỏi hàng đợi.
 */
export const supportThread = <ThrowOnError extends boolean = false>(options: Options<SupportThreadData, ThrowOnError>) => (options.client ?? client).get<SupportThreadResponses, SupportThreadErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/support/threads/{id}',
    ...options
});

/**
 * Master trả lời một luồng
 *
 * Sau lệnh này, người dùng của luồng thấy chấm đỏ trên icon hỗ trợ.
 */
export const supportReply = <ThrowOnError extends boolean = false>(options: Options<SupportReplyData, ThrowOnError>) => (options.client ?? client).post<SupportReplyResponses, SupportReplyErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/support/threads/{id}/reply',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Danh sách đánh giá đã công bố (công khai)
 *
 * CHỈ trả bản đã duyệt, và không kèm `status` — trang này là bản công bố, không phải hàng đợi. Không cần đăng nhập.
 */
export const socialFeedbackList = <ThrowOnError extends boolean = false>(options?: Options<SocialFeedbackListData, ThrowOnError>) => (options?.client ?? client).get<SocialFeedbackListResponses, unknown, ThrowOnError>({ url: '/social-feedback', ...options });

/**
 * Gửi đánh giá, phản ánh, kiến nghị của tổ chức xã hội (công khai)
 *
 * Cửa tiếp nhận ý kiến của tổ chức xã hội tham gia bảo vệ quyền lợi người tiêu dùng. Không cần đăng nhập, giới hạn 5 lượt / 10 phút / IP. Ý kiến vào trạng thái chờ duyệt và CHƯA hiện ở danh sách công bố cho tới khi master duyệt.
 */
export const socialFeedbackSubmit = <ThrowOnError extends boolean = false>(options?: Options<SocialFeedbackSubmitData, ThrowOnError>) => (options?.client ?? client).post<SocialFeedbackSubmitResponses, SocialFeedbackSubmitErrors, ThrowOnError>({
    url: '/social-feedback',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options?.headers
    }
});

/**
 * Hàng đợi duyệt ý kiến (master)
 *
 * Bỏ trống `status` = hàng đợi chờ duyệt. Kèm `status` để xem bản đã xử lý.
 */
export const socialFeedbackReviewQueue = <ThrowOnError extends boolean = false>(options?: Options<SocialFeedbackReviewQueueData, ThrowOnError>) => (options?.client ?? client).get<SocialFeedbackReviewQueueResponses, SocialFeedbackReviewQueueErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/social-feedback/review',
    ...options
});

/**
 * Duyệt hoặc từ chối một ý kiến (master)
 *
 * `published` đưa ý kiến lên trang công bố; `rejected` giữ lại bản ghi nhưng không công bố. Không có đường xoá: đã tiếp nhận thì phải còn vết.
 */
export const socialFeedbackReview = <ThrowOnError extends boolean = false>(options: Options<SocialFeedbackReviewData, ThrowOnError>) => (options.client ?? client).patch<SocialFeedbackReviewResponses, SocialFeedbackReviewErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/social-feedback/{id}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});
